'use client';
import { useState } from 'react';
import { AnimatePresence } from 'motion/react';
import { MenuBox, type MenuItem } from './menu-box';

const defaultMenuItems: MenuItem[] = [
  { title: 'Home', href: '/' },
  { title: 'Work', href: '/work' },
  { title: 'About', href: '/about' },
];

interface AnimatedMenuProps {
  menuItems?: MenuItem[];
}

export default function AnimatedMenu({ menuItems }: AnimatedMenuProps) {
  const [isActive, setIsActive] = useState(false);

  return (
    <>
      <button
        type="button"
        // The trigger renders two bars and no text, so it needs an explicit
        // name and state - without them it reaches assistive tech as an
        // unlabelled button with no indication of whether the menu is open.
        aria-label={isActive ? 'Close menu' : 'Open menu'}
        aria-expanded={isActive}
        className="m-5 w-14 h-14 bg-rose-600 rounded-2xl flex items-center justify-center z-10 relative"
        onClick={() => setIsActive((prev) => !prev)}
      >
        <span
          className={`absolute left-1/2 top-1/2 h-px w-7 -translate-x-1/2 bg-white transition-all duration-300 ${
            isActive ? 'rotate-45' : '-translate-y-1'
          }`}
        />

        <span
          className={`absolute left-1/2 top-1/2 h-px w-7 -translate-x-1/2 bg-white transition-all duration-300 ${
            isActive ? '-rotate-45' : 'translate-y-1'
          }`}
        />
      </button>
      <AnimatePresence mode="wait">
        {isActive && <MenuBox menuItems={menuItems ?? defaultMenuItems} />}
      </AnimatePresence>
    </>
  );
}

'use client';
import { usePathname } from 'next/navigation';
import { motion } from 'motion/react';
import { useState } from 'react';
import Link from './link';
import Curve from './curve';

export interface MenuItem {
  title: string;
  href: string;
}

export const animations = {
  menuSlide: {
    initial: { x: 'calc(100% + 100px)' },

    enter: {
      x: '0',
      transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1] as const },
    },

    exit: {
      x: 'calc(100% + 100px)',
      transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1] as const },
    },
  },
  slide: {
    initial: { x: 80 },

    enter: (i: number) => ({
      x: 0,
      transition: {
        duration: 0.8,
        ease: [0.76, 0, 0.24, 1] as const,
        delay: 0.05 * i,
      },
    }),

    exit: (i: number) => ({
      x: 80,
      transition: {
        duration: 0.8,
        ease: [0.76, 0, 0.24, 1] as const,
        delay: 0.05 * i,
      },
    }),
  },
  scale: {
    open: { scale: 1, transition: { duration: 0.3 } },

    closed: { scale: 0, transition: { duration: 0.4 } },
  },
};

export function MenuBox({ menuItems }: { menuItems: MenuItem[] }) {
  const pathname = usePathname();
  const [selectedIndicator, setSelectedIndicator] = useState(pathname);
  return (
    <motion.div
      variants={animations.menuSlide}
      initial="initial"
      animate="enter"
      exit="exit"
      className="h-screen bg-[rgb(41,41,41)] fixed right-0 top-0 text-white"
    >
      <div className="box-border h-full p-25 flex flex-col justify-between">
        <div
          onMouseLeave={() => {
            setSelectedIndicator(pathname);
          }}
          className="flex flex-col text-6xl gap-3 mt-20"
        >
          <div className="text-[rgb(153,153,153)] border-b-[rgb(153,153,153)] border-b uppercase text-xs mb-10">
            <p>navigation</p>
          </div>
          {menuItems.map((data, index) => (
            <Link
              key={index}
              isActive={selectedIndicator === data.href}
              setSelectedIndicator={setSelectedIndicator}
              data={{ ...data, index }}
            />
          ))}
        </div>
      </div>
      <Curve />
    </motion.div>
  );
}

import { motion } from 'motion/react';
import { animations } from './menu-box';
import Link from 'next/link';

interface CustomLinkProps {
  data: { title: string; href: string; index: number };
  isActive: boolean;
  setSelectedIndicator: React.Dispatch<React.SetStateAction<string>>;
}

export default function CustomLink({
  data,
  isActive,
  setSelectedIndicator,
}: CustomLinkProps) {
  const { title, href, index } = data;
  return (
    <motion.div
      className="relative flex items-center"
      onMouseEnter={() => {
        setSelectedIndicator(href);
      }}
      custom={index}
      variants={animations.slide}
      initial="initial"
      animate="enter"
      exit="exit"
    >
      <motion.div
        variants={animations.scale}
        animate={isActive ? 'open' : 'closed'}
        className="w-2.5 h-2.5 bg-white rounded-full absolute -left-7.5"
      ></motion.div>
      <Link href={href}>{title}</Link>
    </motion.div>
  );
}

import { motion } from 'motion/react';

export default function Curve() {
  const initialPath = `M100 0 L100 ${window.innerHeight} Q-100 ${window.innerHeight / 2} 100 0`;
  const targetPath = `M100 0 L100 ${window.innerHeight} Q100 ${window.innerHeight / 2} 100 0`;
  const curve = {
    initial: {
      d: initialPath,
    },
    enter: {
      d: targetPath,
      transition: { duration: 1, ease: [0.76, 0, 0.24, 1] as const },
    },
    exit: {
      d: initialPath,
      transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1] as const },
    },
  };

  return (
    <svg className="absolute top-0 -left-25 w-25 h-full fill-[rgb(41,41,41)] stroke-none">
      <motion.path
        variants={curve}
        initial="initial"
        animate="enter"
        exit="exit"
      />
    </svg>
  );
}
